if (!data) return [];
const raw = typeof data === 'string' ? JSON.parse(data) : data;
const params = raw?.properties?.parameter ?? raw?.parameter ?? {};
const P = params.PRECTOTCORR ?? params.PRECTOT ?? {};
const T = params.T2M ?? {};
const SW = params.ALLSKY_SFC_SW_DWN ?? {};
return Object.keys(P)
  .map(dt => ({
    date: `${dt.slice(0,4)}-${dt.slice(4,6)}-${dt.slice(6,8)}`,
    precip_mm: Math.max(0, parseFloat(P[dt]) || 0),
    T2M: parseFloat(T[dt]) || 0,
    Solar_Rad: parseFloat(SW[dt]) || 0
  }))
  .filter(r => r.date.length === 10)
  .sort((a,b) => a.date.localeCompare(b.date));

if (!data) return [];
const raw = typeof data === 'string' ? JSON.parse(data) : data;
const ts = (raw?.value?.timeSeries ?? raw?.timeSeries ?? [])[0];
if (!ts) return [];
const vals = ts?.values?.[0]?.value ?? [];
return vals
  .map(v => ({ date: v.dateTime?.slice(0,10), Q_cms: parseFloat(v.value)*0.0283168 }))
  .filter(r => !isNaN(r.Q_cms) && r.Q_cms >= 0)
  .sort((a,b) => a.date.localeCompare(b.date));
